create or replace function public.create_review(p_location_id uuid,p_check_in_id uuid,p_stars smallint,p_cleanliness_pct numeric,p_comment text) returns public.reviews language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare v_review public.reviews; v_check timestamptz; begin if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if; if p_check_in_id is null then raise exception 'CHECK_IN_REQUIRED'; end if; if p_stars < 1 or p_stars > 5 then raise exception 'STARS_OUT_OF_RANGE'; end if; if p_cleanliness_pct is not null and (p_cleanliness_pct < 0 or p_cleanliness_pct > 100) then raise exception 'CLEANLINESS_OUT_OF_RANGE'; end if; select checked_in_at into v_check from public.check_ins where id=p_check_in_id and user_id=auth.uid() and location_id=p_location_id; if not found then raise exception 'CHECK_IN_DOES_NOT_BELONG_TO_USER_AND_LOCATION'; end if; if exists(select 1 from public.reviews r where r.user_id=auth.uid() and r.check_in_id=p_check_in_id) then raise exception 'REVIEW_ALREADY_EXISTS_FOR_CHECK_IN'; end if; insert into public.reviews(location_id,user_id,check_in_id,stars,cleanliness_pct,comment,status) values(p_location_id,auth.uid(),p_check_in_id,p_stars,p_cleanliness_pct,nullif(trim(p_comment),''),'published') returning * into v_review; return v_review; end; $function$;
comment on function public.create_review(uuid,uuid,smallint,numeric,text) is 'Consumer reviews require a user-owned check-in at the same location. Repeat reviews remain allowed on subsequent check-ins; only duplicate reviews for the same check-in are blocked.';
